$ErrorActionPreference="Stop";$V="7.0.0";$R=Split-Path -Parent $MyInvocation.MyCommand.Path;$T=Join-Path $R ".ocr-tmp";$O=Join-Path $R "vendor\tesseract";Remove-Item $T,$O -Recurse -Force -ErrorAction SilentlyContinue;New-Item -ItemType Directory -Force -Path "$T\js","$T\core","$O\core","$O\lang-data"|Out-Null;Push-Location $R
try{npm pack "tesseract.js@$V" --pack-destination $T;npm pack "tesseract.js-core@$V" --pack-destination $T;$J=(Get-ChildItem "$T\tesseract.js-*.tgz"|Select-Object -First 1);$C=(Get-ChildItem "$T\tesseract.js-core-*.tgz"|Select-Object -First 1);tar -xzf $J.FullName -C "$T\js";tar -xzf $C.FullName -C "$T\core";Copy-Item "$T\js\package\dist\tesseract.min.js" "$O\tesseract.min.js";Copy-Item "$T\js\package\dist\worker.min.js" "$O\worker.min.js";$N=@("tesseract-core-simd-lstm.wasm.min.js","tesseract-core-simd-lstm.wasm.js")|Where-Object{Test-Path "$T\core\package\$_"}|Select-Object -First 1;if(!$N){throw "未找到SIMD LSTM Core"};Copy-Item "$T\core\package\$N" "$O\core\$N";$W=$N -replace '\.min\.js$','' -replace '\.js$','';if(!(Test-Path "$T\core\package\$W")){$W="tesseract-core-simd-lstm.wasm"};Copy-Item "$T\core\package\$W" "$O\core\$W";Invoke-WebRequest "https://tessdata.projectnaptha.com/4.0.0_fast/eng.traineddata.gz" -OutFile "$O\lang-data\eng.traineddata.gz";"window.OCR_CORE_PATH='./vendor/tesseract/core/$N';"|Set-Content "$R\ocr-config.js" -Encoding UTF8;Remove-Item $T -Recurse -Force;$S=(Get-ChildItem $O -Recurse -File|Measure-Object Length -Sum).Sum;Write-Host ("精简OCR完成，总大小 {0:N2} MB" -f ($S/1MB)) -ForegroundColor Green;Get-ChildItem $O -Recurse -File|Select-Object FullName,@{N='MB';E={[math]::Round($_.Length/1MB,2)}}}finally{Pop-Location}
